window.QUESTOES = window.QUESTOES || [];
QUESTOES.push(
/* ===== CAP 7 – ABUSO DE AUTORIDADE (extra) ===== */
{c:'c7',b:'FCC',e:`Nos termos do art. 9º da Lei nº 13.869/2019, incorre na pena do crime de decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais a autoridade judiciária que, dentro de prazo razoável, deixar de`,
o:[`ouvir a vítima antes de decretar a prisão.`,`relaxar a prisão manifestamente ilegal; substituir a prisão preventiva por medida cautelar diversa ou conceder liberdade provisória, quando manifestamente cabível; ou deferir liminar ou ordem de habeas corpus, quando manifestamente cabível.`,`designar audiência de instrução no prazo de 30 dias.`,`comunicar a prisão ao Conselho Nacional de Justiça.`,`intimar o Ministério Público para manifestação.`],a:1,
x:`Art. 9º, parágrafo único, I a III. A pena é de detenção de 1 a 4 anos e multa.`},

{c:'c7',b:'Vunesp',e:`Decretar a condução coercitiva de testemunha ou investigado manifestamente descabida ou sem prévia intimação de comparecimento ao juízo configura, nos termos da Lei nº 13.869/2019,`,
o:[`mera irregularidade processual.`,`crime punido com detenção de 1 a 4 anos e multa.`,`infração administrativa.`,`crime de constrangimento ilegal do Código Penal.`,`fato atípico, se houver ordem judicial.`],a:1,
x:`Art. 10. O STF, nas ADPFs 395 e 444, também declarou incompatível com a Constituição a condução coercitiva de investigados ou réus para interrogatório.`},

{c:'c7',b:'FCC',e:`Incorre no crime do art. 15 da Lei de Abuso de Autoridade quem prossegue com o interrogatório`,
o:[`após o horário de expediente.`,`de pessoa que tenha decidido exercer o direito ao silêncio, ou de pessoa que tenha optado por ser assistida por advogado ou defensor público, sem a presença de seu patrono.`,`de pessoa que confessou o crime.`,`de testemunha que se contradisse.`,`de investigado reincidente.`],a:1,
x:`Art. 15, parágrafo único, I e II. O caput pune constranger a depor, sob ameaça de prisão, quem deve guardar segredo profissional.`},

{c:'c7',b:'Vunesp',e:`Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia configura`,
o:[`apenas falta disciplinar.`,`o crime do art. 19 da Lei nº 13.869/2019, punido com detenção de 1 a 4 anos e multa.`,`crime de prevaricação.`,`fato atípico.`,`crime de tortura.`],a:1,
x:`Art. 19. Incorre na mesma pena o magistrado que, ciente do impedimento ou da demora, deixa de tomar as providências para saná-lo ou não envia o pedido à autoridade competente.`},

{c:'c7',b:'FCC',e:`Nos termos do art. 20 da Lei de Abuso de Autoridade, constitui crime impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado. Incorre na mesma pena quem impede o preso, o réu solto ou o investigado de`,
o:[`receber visitas de familiares nos fins de semana.`,`entrevistar-se pessoal e reservadamente com seu advogado ou defensor, por prazo razoável, antes de audiência judicial, e de sentar-se ao seu lado e com ele comunicar-se durante a audiência, salvo no curso de interrogatório ou no caso de audiência realizada por videoconferência.`,`utilizar telefone celular na delegacia.`,`ter acesso à imprensa.`,`escolher o horário da audiência.`],a:1,
x:`Art. 20 e parágrafo único (detenção de 6 meses a 2 anos e multa).`},

{c:'c7',b:'Vunesp',e:`Policial que, mediante violência ou grave ameaça, coage o morador a franquear-lhe o acesso a sua casa, sem ordem judicial e fora das hipóteses legais,`,
o:[`age licitamente, se suspeitar de crime.`,`incorre no crime do art. 22, § 1º, I, da Lei nº 13.869/2019, com pena de detenção de 1 a 4 anos e multa.`,`comete apenas falta disciplinar.`,`comete crime de tortura.`,`só comete crime se nada for encontrado.`],a:1,
x:`Art. 22, § 1º, I. O consentimento obtido sob coação não legitima a entrada. Não há crime se o ingresso for para prestar socorro ou houver fundados indícios de flagrante delito ou desastre (§ 2º).`},

{c:'c7',b:'FCC',e:`Após uma ocorrência com morte, policial altera a posição do corpo e coloca uma arma junto à vítima para simular confronto e eximir-se de responsabilidade. A conduta corresponde ao crime de`,
o:[`favorecimento pessoal.`,`inovar artificiosamente, no curso de diligência, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade, previsto no art. 23 da Lei nº 13.869/2019.`,`falso testemunho.`,`denunciação caluniosa, exclusivamente.`,`dano qualificado.`],a:1,
x:`Art. 23 (detenção de 1 a 4 anos e multa). Incorre também quem pratica a conduta para eximir-se de responsabilidade civil ou administrativa por excesso praticado na diligência (parágrafo único, I). O crime de homicídio, se houver, é apurado separadamente.`},

{c:'c7',b:'Vunesp',e:`Constranger, sob violência ou grave ameaça, funcionário ou empregado de instituição hospitalar a admitir para tratamento pessoa cujo óbito já tenha ocorrido, com o fim de alterar local ou momento de crime, prejudicando sua apuração, é crime previsto`,
o:[`no art. 24 da Lei nº 13.869/2019, punido com detenção de 1 a 4 anos e multa, além da pena correspondente à violência.`,`apenas no Código Penal, como fraude processual.`,`no Código Penal Militar, exclusivamente.`,`na Lei de Tortura.`,`no Estatuto do Desarmamento.`],a:0,
x:`Art. 24 da Lei 13.869/2019. Busca coibir o "socorro" de cadáveres para desfazer a cena do crime.`},

{c:'c7',b:'FCC',e:`Proceder à obtenção de prova, em procedimento de investigação ou fiscalização, por meio manifestamente ilícito`,
o:[`é conduta lícita se a prova confirmar o crime.`,`configura o crime do art. 25 da Lei nº 13.869/2019, incorrendo na mesma pena quem faz uso da prova, em desfavor do investigado ou fiscalizado, com prévio conhecimento de sua ilicitude.`,`gera apenas a nulidade da prova, sem consequência penal.`,`configura crime somente se praticado por juiz.`,`configura crime de tortura.`],a:1,
x:`Art. 25 e parágrafo único (detenção de 1 a 4 anos e multa).`},

{c:'c7',b:'Vunesp',e:`Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, à falta de qualquer indício da prática de crime, de ilícito funcional ou de infração administrativa, é crime. Contudo, segundo a lei, não há crime quando se tratar de`,
o:[`inquérito policial instaurado por delegado.`,`sindicância ou investigação preliminar sumária, devidamente justificada.`,`procedimento instaurado a pedido da vítima.`,`investigação de crime hediondo.`,`procedimento sigiloso.`],a:1,
x:`Art. 27 e parágrafo único da Lei 13.869/2019.`},

{c:'c7',b:'FCC',e:`Nos termos da Lei nº 13.869/2019, faz coisa julgada em âmbito cível, assim como no administrativo-disciplinar, a sentença penal que reconhecer ter sido o ato praticado em`,
o:[`erro de proibição.`,`estado de necessidade, legítima defesa, estrito cumprimento de dever legal ou exercício regular de direito.`,`embriaguez voluntária.`,`coação moral resistível.`,`obediência a ordem manifestamente ilegal.`],a:1,
x:`Art. 8º. O art. 7º acrescenta que não se pode mais questionar a existência ou a autoria do fato quando já decididas no juízo criminal.`},

{c:'c7',b:'Vunesp',e:`Deixar de comunicar imediatamente a prisão de qualquer pessoa e o local onde se encontra à sua família ou à pessoa por ela indicada configura, nos termos da Lei de Abuso de Autoridade,`,
o:[`mera irregularidade administrativa.`,`crime punido com detenção de 6 meses a 2 anos e multa.`,`crime punido com reclusão de 2 a 8 anos.`,`crime somente se o preso for menor de idade.`,`fato atípico, se a comunicação for feita ao juiz.`],a:1,
x:`Art. 12, parágrafo único, II, em sintonia com o art. 5º, LXII, da CF.`},

/* ===== CAP 8 – TORTURA (extra) ===== */
{c:'c8',b:'Vunesp',e:`Fulano, com emprego de violência, causa intenso sofrimento físico a Beltrano para obrigá-lo a assaltar um posto de gasolina. Nos termos da Lei nº 9.455/1997, Fulano pratica`,
o:[`tortura-castigo.`,`tortura para provocar ação ou omissão de natureza criminosa (art. 1º, I, "b").`,`apenas constrangimento ilegal.`,`tortura discriminatória.`,`lesão corporal grave.`],a:1,
x:`Art. 1º, I, "b". Se Beltrano praticar o roubo, Fulano responde também pelo roubo, como autor mediato (coação moral irresistível).`},

{c:'c8',b:'FCC',e:`Um pai, para castigar o filho de 10 anos por mau comportamento, amarra-o e o queima com ferro quente, causando-lhe intenso sofrimento. A conduta configura`,
o:[`maus-tratos (art. 136 do CP), por haver finalidade educativa.`,`tortura-castigo (art. 1º, II, da Lei nº 9.455/1997), com aumento de pena por ser a vítima criança.`,`lesão corporal leve.`,`crime do art. 232 do ECA.`,`exercício regular do poder familiar.`],a:1,
x:`Há vínculo de guarda e intenso sofrimento como castigo: tortura-castigo (reclusão de 2 a 8 anos), com aumento de 1/6 a 1/3 por ser criança (§ 4º, II). Nos maus-tratos, há abuso dos meios de correção, sem a intenção de causar intenso sofrimento.`},

{c:'c8',b:'Vunesp',e:`Se o crime de tortura é cometido mediante sequestro, a pena`,
o:[`é aplicada em dobro.`,`é aumentada de 1/6 até 1/3.`,`passa a ser de reclusão de 8 a 16 anos.`,`é aumentada de metade.`,`não sofre alteração.`],a:1,
x:`Art. 1º, § 4º, III, da Lei 9.455/1997.`},

{c:'c8',b:'FCC',e:`Se da tortura resulta lesão corporal de natureza grave ou gravíssima, a pena é de`,
o:[`reclusão, de 2 a 8 anos.`,`reclusão, de 4 a 10 anos.`,`reclusão, de 8 a 16 anos.`,`detenção, de 1 a 4 anos.`,`reclusão, de 3 a 12 anos.`],a:1,
x:`Art. 1º, § 3º, primeira parte. Com resultado morte: reclusão de 8 a 16 anos.`},

{c:'c8',b:'Vunesp',e:`O comandante de guarnição que presencia seus subordinados torturando um preso para obter confissão e, podendo e devendo evitar, nada faz,`,
o:[`não responde por nada, pois não praticou a tortura.`,`responde pelo crime de omissão do art. 1º, § 2º, da Lei nº 9.455/1997, punido com detenção de 1 a 4 anos.`,`responde por prevaricação, apenas.`,`responde pela tortura-prova, com pena de 2 a 8 anos, obrigatoriamente.`,`responde por abuso de autoridade.`],a:1,
x:`A lei criou figura específica para quem se omite tendo o dever de evitar ou apurar a tortura (§ 2º). A perda do cargo também se aplica.`},

{c:'c8',b:'FCC',e:`O diretor de presídio que, sem previsão legal nem decisão disciplinar regular, determina que um preso fique três dias sem alimentação como forma de punição`,
o:[`pratica falta disciplinar, apenas.`,`incorre no art. 1º, § 1º, da Lei nº 9.455/1997, por submeter pessoa presa a sofrimento físico ou mental por meio de ato não previsto em lei ou não resultante de medida legal.`,`pratica conduta autorizada pela Lei de Execução Penal.`,`pratica abuso de autoridade do art. 13.`,`não comete crime, pois não houve violência.`],a:1,
x:`O § 1º não exige violência ou grave ameaça: basta submeter o preso a sofrimento por ato não previsto em lei. Pena: reclusão de 2 a 8 anos, aumentada por ser agente público.`},

{c:'c8',b:'Vunesp',e:`Segundo a Lei de Crimes Hediondos e o entendimento do STF, ao condenado por tortura`,
o:[`pode ser concedido indulto, pois a Constituição só veda graça e anistia.`,`é vedada a concessão de anistia, graça e indulto.`,`pode ser concedida fiança arbitrada pelo juiz.`,`é vedada a progressão de regime.`,`é vedada a liberdade provisória em qualquer hipótese.`],a:1,
x:`Art. 2º, I, da Lei 8.072/1990 (válido segundo o STF). A Lei 9.455/97 fala só em graça e anistia, e a CF não menciona o indulto: essa é a pegadinha.`},

{c:'c8',b:'FCC',e:`Policiais militares em serviço praticam tortura contra um civil. Após a Lei nº 13.491/2017, que ampliou o conceito de crime militar, segundo o STJ, a competência para julgar o crime é da`,
o:[`Justiça Federal.`,`Justiça Militar estadual.`,`Justiça comum estadual, em qualquer caso.`,`Justiça Eleitoral.`,`Tribunal do Júri.`],a:1,
x:`A Lei 13.491/2017 passou a considerar crimes militares os previstos na legislação penal comum quando praticados por militar em serviço (art. 9º, II, CPM). Atenção: crime doloso contra a vida de civil continua com o Tribunal do Júri.`},

{c:'c8',b:'Vunesp',e:`Ao contrário da Convenção da ONU contra a Tortura, que define a tortura como ato praticado por funcionário público ou com sua aquiescência, a Lei nº 9.455/1997`,
o:[`só pune a tortura praticada por agentes do Estado.`,`tipificou a tortura do art. 1º, I, como crime comum, que pode ser praticado por qualquer pessoa, e prevê aumento de pena quando cometida por agente público.`,`não prevê aumento de pena para agentes públicos.`,`só se aplica a presos.`,`só pune a tortura física.`],a:1,
x:`A lei brasileira foi além da Convenção. A tortura-castigo (art. 1º, II) é crime próprio, por exigir vínculo de guarda, poder ou autoridade.`},

/* ===== CAP 9 – MARIA DA PENHA (extra) ===== */
{c:'c9',b:'FCC',e:`No atendimento à mulher em situação de violência doméstica, a autoridade policial deverá, se necessário,`,
o:[`entregar ao agressor as chaves da residência.`,`acompanhar a ofendida para assegurar a retirada de seus pertences do local da ocorrência ou do domicílio familiar.`,`obrigar a ofendida a permanecer no lar.`,`conduzir a ofendida ao Conselho Tutelar.`,`designar audiência de conciliação.`],a:1,
x:`Art. 11, IV, da Lei Maria da Penha.`},

{c:'c9',b:'Vunesp',e:`O agressor, policial militar com porte de arma funcional, tem contra si medida protetiva de suspensão da posse ou restrição do porte de armas. Nos termos do art. 22, § 2º, da Lei Maria da Penha,`,
o:[`a medida não se aplica a policiais, por necessitarem da arma para o serviço.`,`o juiz comunicará a corporação, determinará a restrição do porte e o superior imediato do agressor ficará responsável pelo cumprimento, sob pena de incorrer nos crimes de prevaricação ou de desobediência, conforme o caso.`,`a restrição depende de autorização do Comandante-Geral.`,`o policial deverá ser exonerado.`,`a arma deverá ser entregue à ofendida.`],a:1,
x:`Art. 22, § 2º, para os agentes do art. 6º do Estatuto do Desarmamento, como policiais e militares.`},

{c:'c9',b:'FCC',e:`Nos termos da Lei Maria da Penha, em qualquer fase do inquérito policial ou da instrução criminal, caberá`,
o:[`a transação penal.`,`a prisão preventiva do agressor.`,`a suspensão condicional do processo.`,`a composição civil dos danos.`,`a aplicação de cesta básica.`],a:1,
x:`Art. 20. O juiz pode revogar a preventiva se verificar falta de motivo para que subsista e voltar a decretá-la se sobrevierem razões que a justifiquem (parágrafo único).`},

{c:'c9',b:'Vunesp',e:`Uma das diretrizes da inquirição da mulher em situação de violência doméstica, prevista no art. 10-A da Lei Maria da Penha, é a`,
o:[`acareação obrigatória com o agressor.`,`não revitimização da depoente, evitando sucessivas inquirições sobre o mesmo fato nos âmbitos criminal, cível e administrativo, bem como questionamentos sobre a vida privada.`,`gravação proibida do depoimento.`,`presença obrigatória do agressor.`,`realização do depoimento apenas em juízo.`],a:1,
x:`Art. 10-A, § 1º, III. Também são diretrizes a salvaguarda da integridade da mulher e a garantia de que não terá contato direto com investigados ou suspeitos.`},

{c:'c9',b:'FCC',e:`Um ex-namorado, com quem a vítima não morava, a agride em razão do término do relacionamento, ocorrido dois anos antes. Nos termos da Lei Maria da Penha,`,
o:[`a lei não se aplica, pois o relacionamento já terminou.`,`a lei se aplica, por se tratar de relação íntima de afeto em que o agressor conviveu com a ofendida, independentemente de coabitação.`,`a lei só se aplica se tiverem filhos em comum.`,`a lei só se aplica se o namoro tiver durado mais de um ano.`,`a lei não se aplica a namoros.`],a:1,
x:`Art. 5º, III ("conviva ou tenha convivido"), e Súmula 600 STJ.`},

{c:'c9',b:'Vunesp',e:`O agressor é condenado por lesão corporal praticada contra a companheira no ambiente doméstico. Segundo a Súmula 588 do STJ,`,
o:[`a pena deve ser substituída por cesta básica.`,`é impossível a substituição da pena privativa de liberdade por restritiva de direitos.`,`a pena deve ser convertida em multa.`,`aplica-se o perdão judicial.`,`cabe transação penal.`],a:1,
x:`Súmula 588 STJ: crime ou contravenção com violência ou grave ameaça no ambiente doméstico impede a substituição. O sursis (suspensão condicional da pena), porém, não é vedado por ela.`},

/* ===== CAP 10 – RACISMO (extra) ===== */
{c:'c10',b:'Vunesp',e:`Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, por motivo de discriminação de raça ou cor, é crime punido com`,
o:[`reclusão, de 2 a 5 anos.`,`reclusão, de 1 a 3 anos.`,`detenção, de 6 meses a 1 ano.`,`reclusão, de 3 a 5 anos.`,`reclusão, de 2 a 4 anos.`],a:0,
x:`Art. 3º da Lei 7.716/89. Incorre na mesma pena quem obsta a promoção funcional por discriminação (parágrafo único).`},

{c:'c10',b:'FCC',e:`Negar ou obstar emprego em empresa privada por motivo de discriminação de raça, cor, etnia, religião ou procedência nacional é crime punido com`,
o:[`reclusão, de 1 a 3 anos.`,`reclusão, de 2 a 5 anos.`,`detenção, de 1 a 2 anos.`,`multa, apenas.`,`reclusão, de 3 a 5 anos.`],a:1,
x:`Art. 4º da Lei 7.716/89. Também incorre quem deixa de conceder equipamentos ou impõe tratamento diferenciado no trabalho por esses motivos (§ 1º).`},

{c:'c10',b:'Vunesp',e:`O dono de uma loja que se recusa a atender um cliente por causa da cor de sua pele comete crime previsto na Lei nº 7.716/1989, punido com`,
o:[`reclusão, de 1 a 3 anos.`,`reclusão, de 3 a 5 anos.`,`detenção, de 3 meses a 1 ano.`,`reclusão, de 2 a 5 anos.`,`apenas multa.`],a:0,
x:`Art. 5º: recusar ou impedir acesso a estabelecimento comercial, negando-se a servir, atender ou receber cliente ou comprador.`},

{c:'c10',b:'FCC',e:`Impedir o acesso ou recusar atendimento em restaurantes, bares, confeitarias ou locais semelhantes abertos ao público, por motivo de discriminação racial, é crime punido com`,
o:[`reclusão, de 1 a 3 anos.`,`reclusão, de 3 a 5 anos.`,`reclusão, de 2 a 4 anos.`,`detenção, de 6 meses a 2 anos.`,`reclusão, de 2 a 5 anos.`],a:0,
x:`Art. 8º da Lei 7.716/89.`},

{c:'c10',b:'Vunesp',e:`Impedir ou obstar o acesso de alguém ao serviço em qualquer ramo das Forças Armadas, por motivo de discriminação racial, é crime punido com`,
o:[`reclusão, de 1 a 3 anos.`,`reclusão, de 2 a 4 anos.`,`reclusão, de 3 a 5 anos.`,`detenção, de 1 a 2 anos.`,`reclusão, de 4 a 8 anos.`],a:1,
x:`Art. 13. A mesma pena (2 a 4 anos) vale para impedir o casamento ou a convivência familiar e social (art. 14).`},

{c:'c10',b:'FCC',e:`Se o crime de recusar, negar ou impedir a inscrição ou ingresso de aluno em estabelecimento de ensino, por motivo de discriminação racial, for praticado contra menor de 18 anos, a pena`,
o:[`é reduzida de 1/3.`,`é agravada de 1/3.`,`é aplicada em dobro.`,`é aumentada de metade.`,`não se altera.`],a:1,
x:`Art. 6º, parágrafo único, da Lei 7.716/89. A pena base é de reclusão de 3 a 5 anos.`},

{c:'c10',b:'Vunesp',e:`A injúria racial (art. 2º-A da Lei nº 7.716/1989) tem a pena aumentada de metade quando cometida`,
o:[`contra funcionário público.`,`mediante concurso de 2 ou mais pessoas.`,`por meio de rede social.`,`durante o repouso noturno.`,`contra pessoa idosa.`],a:1,
x:`Art. 2º-A, parágrafo único. Se praticada por funcionário público em serviço, aumenta-se de 1/3 até a metade (art. 20-B); em contexto recreativo, também de 1/3 até a metade (art. 20-A).`},

{c:'c10',b:'FCC',e:`Praticar, induzir ou incitar a discriminação racial por meio de publicação em redes sociais é crime punido com`,
o:[`reclusão, de 1 a 3 anos, e multa.`,`reclusão, de 2 a 5 anos, e multa.`,`detenção, de 6 meses a 1 ano.`,`reclusão, de 3 a 6 anos.`,`apenas multa.`],a:1,
x:`Art. 20, § 2º. A forma simples (caput) tem pena de reclusão de 1 a 3 anos e multa.`},

{c:'c10',b:'Vunesp',e:`Torcedor que, em estádio de futebol durante uma partida, pratica ato de discriminação racial contra um jogador incorre, nos termos do art. 20, § 2º-A, da Lei nº 7.716/1989, na pena de`,
o:[`reclusão, de 1 a 3 anos, apenas.`,`reclusão, de 2 a 5 anos, e proibição de frequência, por 3 anos, a locais destinados a práticas esportivas, artísticas ou culturais destinadas ao público, conforme o caso.`,`multa e advertência.`,`detenção, de 6 meses a 2 anos.`,`reclusão, de 4 a 8 anos.`],a:1,
x:`Art. 20, § 2º-A, incluído pela Lei 14.532/2023. Se a ofensa for dirigida a pessoa determinada, pode configurar injúria racial (art. 2º-A).`},

{c:'c10',b:'FCC',e:`Nos termos do art. 20, § 2º-B, da Lei nº 7.716/1989, sem prejuízo da pena correspondente à violência, incorre nas mesmas penas do caput quem`,
o:[`deixa de frequentar culto religioso.`,`obstar, impedir ou empregar violência contra quaisquer manifestações ou práticas religiosas.`,`critica dogmas religiosos em ambiente acadêmico.`,`muda de religião.`,`se recusa a participar de cerimônia religiosa.`],a:1,
x:`Proteção às religiões, incluída pela Lei 14.532/2023. A crítica e o debate religioso, sem incitação ao ódio, continuam protegidos pela liberdade de expressão e de crença.`},

{c:'c10',b:'Vunesp',e:`Segundo o art. 20-C da Lei nº 7.716/1989, na interpretação da lei, o juiz deve considerar como discriminatória qualquer atitude ou tratamento dado à pessoa ou a grupos minoritários que cause`,
o:[`prejuízo econômico comprovado.`,`constrangimento, humilhação, vergonha, medo ou exposição indevida, e que usualmente não se dispensaria a outros grupos em razão da cor, etnia, religião ou procedência.`,`lesão corporal.`,`dano moral apurado em ação cível.`,`apenas ofensa verbal pública.`],a:1,
x:`Literalidade do art. 20-C (Lei 14.532/2023).`},

/* ===== CAP 11 – AMBIENTAIS (extra) ===== */
{c:'c11',b:'FCC',e:`Nos termos do art. 2º da Lei nº 9.605/1998, incide nas penas cominadas aos crimes ambientais, na medida de sua culpabilidade, o diretor, o administrador ou o gerente de pessoa jurídica que,`,
o:[`em qualquer hipótese, ocupe cargo na empresa à época do fato.`,`sabendo da conduta criminosa de outrem, deixar de impedir a sua prática, quando podia agir para evitá-la.`,`não tenha formação técnica ambiental.`,`assine o balanço anual da empresa.`,`seja sócio majoritário, ainda que desconheça o fato.`],a:1,
x:`Art. 2º. A lei não admite responsabilidade penal objetiva do dirigente: exige conhecimento da conduta e possibilidade de evitá-la.`},

{c:'c11',b:'Vunesp',e:`A Lei nº 9.605/1998 permite a desconsideração da personalidade jurídica`,
o:[`apenas em caso de fraude comprovada.`,`sempre que sua personalidade for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente.`,`apenas para sociedades anônimas.`,`somente após o trânsito em julgado da condenação criminal.`,`apenas com autorização do Ibama.`],a:1,
x:`Art. 4º. Adota-se a teoria menor da desconsideração, que dispensa prova de abuso ou confusão patrimonial.`},

{c:'c11',b:'FCC',e:`Entre as penas restritivas de direitos aplicáveis à pessoa física na Lei de Crimes Ambientais, está o recolhimento domiciliar, que se baseia`,
o:[`no monitoramento eletrônico obrigatório.`,`na autodisciplina e senso de responsabilidade do condenado, que deverá, sem vigilância, trabalhar, frequentar curso ou exercer atividade autorizada, permanecendo recolhido nos dias e horários de folga em sua residência.`,`na permanência integral em casa, sem possibilidade de trabalho.`,`na prisão em regime semiaberto.`,`na visita diária de oficial de justiça.`],a:1,
x:`Arts. 8º, V, e 13 da Lei 9.605/1998.`},

{c:'c11',b:'Vunesp',e:`A pena de interdição temporária de direitos, na Lei de Crimes Ambientais, consiste na proibição de contratar com o Poder Público, de receber incentivos fiscais e de participar de licitações, pelo prazo de`,
o:[`1 ano para crimes dolosos e 6 meses para culposos.`,`5 anos, no caso de crimes dolosos, e de 3 anos, no de crimes culposos.`,`10 anos, em qualquer caso.`,`2 anos para crimes dolosos e 1 ano para culposos.`,`até o pagamento da multa.`],a:1,
x:`Art. 10. Para a pessoa jurídica, a proibição de contratar com o Poder Público pode chegar a 10 anos (art. 22, § 3º).`},

{c:'c11',b:'FCC',e:`A prestação pecuniária, como pena restritiva de direitos na Lei de Crimes Ambientais, consiste no pagamento em dinheiro à vítima ou a entidade pública ou privada com fim social, de importância fixada pelo juiz,`,
o:[`não inferior a 10 nem superior a 100 salários mínimos.`,`não inferior a 1 salário mínimo nem superior a 360 salários mínimos, sendo o valor deduzido de eventual reparação civil.`,`livremente arbitrada, sem limites.`,`não inferior a 5 salários mínimos, sem limite máximo.`,`equivalente ao dobro do dano.`],a:1,
x:`Art. 12 da Lei 9.605/1998.`},

{c:'c11',b:'Vunesp',e:`É circunstância que atenua a pena nos crimes ambientais, nos termos do art. 14 da Lei nº 9.605/1998,`,
o:[`ter o agente cometido a infração à noite.`,`o baixo grau de instrução ou escolaridade do agente.`,`a reincidência em crime ambiental.`,`ter atingido espécie ameaçada de extinção.`,`ter o agente obtido vantagem pecuniária.`],a:1,
x:`Atenuantes: baixo grau de instrução, arrependimento com reparação espontânea, comunicação prévia do perigo e colaboração com a fiscalização. As demais alternativas são agravantes (art. 15).`},

{c:'c11',b:'FCC',e:`Na Lei de Crimes Ambientais, a multa que se revelar ineficaz, ainda que aplicada no valor máximo,`,
o:[`deve ser substituída por prisão.`,`poderá ser aumentada até 3 vezes, tendo em vista o valor da vantagem econômica auferida.`,`poderá ser aumentada até 10 vezes.`,`deve ser convertida em prestação de serviços.`,`fica extinta.`],a:1,
x:`Art. 18 da Lei 9.605/1998.`},

{c:'c11',b:'Vunesp',e:`Pescar mediante a utilização de explosivos ou de substâncias que, em contato com a água, produzam efeito semelhante é crime punido com`,
o:[`detenção, de 1 a 3 anos, ou multa.`,`reclusão, de 1 a 5 anos.`,`detenção, de 6 meses a 1 ano.`,`apenas multa.`,`reclusão, de 2 a 8 anos.`],a:1,
x:`Art. 35. Pescar em período proibido ou em local interditado (art. 34) é punido com detenção de 1 a 3 anos ou multa, ou ambas.`},

{c:'c11',b:'FCC',e:`Provocar incêndio em mata ou floresta é crime previsto no art. 41 da Lei nº 9.605/1998, punido com`,
o:[`reclusão, de 2 a 4 anos, e multa; se culposo, detenção de 6 meses a 1 ano e multa.`,`detenção, de 1 a 3 anos, em qualquer caso.`,`reclusão, de 1 a 5 anos.`,`reclusão, de 4 a 8 anos.`,`apenas multa, se culposo.`],a:0,
x:`Art. 41 e parágrafo único. Soltar balões que possam provocar incêndios é o art. 42 (detenção de 1 a 3 anos ou multa, ou ambas).`},

{c:'c11',b:'Vunesp',e:`Causar poluição de qualquer natureza em níveis tais que resultem ou possam resultar em danos à saúde humana, ou que provoquem a mortandade de animais ou a destruição significativa da flora, é crime punido com`,
o:[`detenção, de 3 meses a 1 ano.`,`reclusão, de 1 a 4 anos, e multa; na forma culposa, detenção de 6 meses a 1 ano e multa.`,`reclusão, de 4 a 10 anos.`,`apenas multa administrativa.`,`detenção, de 1 a 3 anos, sem forma culposa.`],a:1,
x:`Art. 54, caput e § 1º. As formas qualificadas do § 2º (área imprópria para ocupação humana, interrupção do abastecimento de água etc.) têm pena de reclusão de 1 a 5 anos.`},

{c:'c11',b:'FCC',e:`Nos termos do art. 70, § 1º, da Lei nº 9.605/1998, são autoridades competentes para lavrar auto de infração ambiental e instaurar processo administrativo`,
o:[`quaisquer servidores públicos, de qualquer órgão.`,`os funcionários de órgãos ambientais integrantes do SISNAMA, designados para as atividades de fiscalização, bem como os agentes das Capitanias dos Portos, do Ministério da Marinha.`,`apenas os membros do Ministério Público.`,`apenas os delegados de polícia.`,`os prefeitos municipais, exclusivamente.`],a:1,
x:`Art. 70, § 1º. Qualquer pessoa pode representar às autoridades (§ 2º), e a autoridade que souber da infração é obrigada a apurá-la, sob pena de corresponsabilidade (§ 3º).`},

{c:'c11',b:'Vunesp',e:`O valor da multa administrativa por infração ambiental, nos termos do art. 75 da Lei nº 9.605/1998, terá`,
o:[`mínimo de R$ 100,00 e máximo de R$ 1.000.000,00.`,`mínimo de R$ 50,00 e máximo de R$ 50.000.000,00.`,`mínimo de 1 e máximo de 360 salários mínimos.`,`valor fixo de R$ 5.000,00.`,`mínimo de R$ 500,00, sem limite máximo.`],a:1,
x:`Art. 75 da Lei 9.605/1998.`},

/* ===== CAP 12 – HEDIONDOS (extra) ===== */
{c:'c12',b:'Vunesp',e:`O roubo qualificado pelo resultado morte (latrocínio)`,
o:[`não é hediondo, por ser crime contra o patrimônio.`,`é crime hediondo, consumado ou tentado.`,`só é hediondo se praticado com arma de fogo.`,`é hediondo apenas na forma consumada.`,`é equiparado a hediondo, sem integrar o rol.`],a:1,
x:`Art. 1º, II, "c", da Lei 8.072/1990: roubo qualificado pelo resultado lesão corporal grave ou morte.`},

{c:'c12',b:'FCC',e:`O estupro na sua forma simples (art. 213, caput, do Código Penal)`,
o:[`não é hediondo; só as formas qualificadas o são.`,`é crime hediondo.`,`é hediondo apenas se houver lesão grave.`,`é hediondo apenas se a vítima for menor de 18 anos.`,`é crime de menor potencial ofensivo.`],a:1,
x:`Art. 1º, V: estupro (art. 213, caput e §§ 1º e 2º). O estupro de vulnerável também é hediondo (inciso VI).`},

{c:'c12',b:'Vunesp',e:`O homicídio simples (art. 121, caput, do CP) é considerado hediondo quando`,
o:[`praticado contra criança.`,`praticado em atividade típica de grupo de extermínio, ainda que cometido por um só agente.`,`praticado com arma de fogo.`,`praticado por motivo de ciúme.`,`praticado à noite.`],a:1,
x:`Art. 1º, I, da Lei 8.072/1990. Fora dessa hipótese, só o homicídio qualificado é hediondo.`},

{c:'c12',b:'FCC',e:`Segundo a jurisprudência do STJ, o homicídio qualificado-privilegiado (por exemplo, motivo de relevante valor moral com emprego de meio cruel)`,
o:[`é hediondo, pois prevalece a qualificadora.`,`não é considerado hediondo.`,`é equiparado a hediondo.`,`só é hediondo se a qualificadora for subjetiva.`,`é hediondo se praticado por agente público.`],a:1,
x:`O privilégio (de natureza subjetiva) é incompatível com o caráter hediondo. O homicídio privilegiado só pode coexistir com qualificadoras objetivas, como o meio cruel.`},

{c:'c12',b:'Vunesp',e:`É crime hediondo previsto no parágrafo único do art. 1º da Lei nº 8.072/1990 o`,
o:[`crime de genocídio.`,`crime de associação para o tráfico.`,`porte ilegal de arma de fogo de uso permitido.`,`crime de corrupção passiva.`,`crime de lavagem de dinheiro.`],a:0,
x:`Parágrafo único: genocídio; posse ou porte de arma de uso proibido; comércio ilegal e tráfico internacional de armas; organização criminosa voltada a hediondo; crimes do CPM correspondentes; e os do § 1º do art. 240 e do art. 241-B do ECA.`},

{c:'c12',b:'FCC',e:`A falsificação, corrupção, adulteração ou alteração de produto destinado a fins terapêuticos ou medicinais (art. 273 do CP)`,
o:[`é crime de menor potencial ofensivo.`,`é crime hediondo.`,`é contravenção penal.`,`só é hediondo se resultar morte.`,`é crime equiparado ao tráfico de drogas.`],a:1,
x:`Art. 1º, VII-B, da Lei 8.072/1990. A pena do art. 273, porém, foi declarada inconstitucional pelo STF no caso do § 1º-B, I (importação de medicamento sem registro), aplicando-se o preceito anterior.`},

{c:'c12',b:'Vunesp',e:`Com a Lei nº 14.811/2024, passou a ser crime hediondo o sequestro e cárcere privado`,
o:[`praticado contra qualquer pessoa.`,`cometido contra menor de 18 anos.`,`praticado por mais de 15 dias.`,`praticado contra pessoa idosa.`,`praticado com fim libidinoso.`],a:1,
x:`Art. 1º, XI, da Lei 8.072/1990 (art. 148, § 1º, IV, do CP). A mesma lei incluiu o induzimento ao suicídio ou automutilação pela internet e o tráfico de pessoas contra criança ou adolescente.`},

{c:'c12',b:'FCC',e:`O condenado primário por crime hediondo com resultado morte (como o latrocínio) poderá progredir de regime após cumprir`,
o:[`40% da pena, permitido o livramento condicional.`,`50% da pena, vedado o livramento condicional.`,`60% da pena.`,`2/3 da pena.`,`1/6 da pena.`],a:1,
x:`Art. 112, VI, "a", da LEP (Pacote Anticrime).`},

{c:'c12',b:'Vunesp',e:`Segundo a Súmula Vinculante 26, para efeito de progressão de regime no cumprimento de pena por crime hediondo ou equiparado, o juízo da execução`,
o:[`deve negar a progressão, por força da Lei nº 8.072/1990.`,`observará a inconstitucionalidade do antigo art. 2º da Lei nº 8.072/1990, podendo determinar, de modo fundamentado, a realização de exame criminológico.`,`deve conceder a progressão automaticamente após 1/6 da pena.`,`deve exigir o cumprimento de 2/3 da pena.`,`não pode determinar exame criminológico.`],a:1,
x:`SV 26. Depois da Lei 14.843/2024, o exame criminológico passou a ser exigido por lei para a progressão (art. 112, § 1º, da LEP).`},

{c:'c12',b:'FCC',e:`Tortura, tráfico ilícito de entorpecentes e terrorismo, em relação à Lei nº 8.072/1990,`,
o:[`integram o rol de crimes hediondos do art. 1º.`,`não são crimes hediondos, mas são equiparados a eles, recebendo o mesmo tratamento constitucional e legal mais rigoroso.`,`não recebem nenhum tratamento diferenciado.`,`são imprescritíveis.`,`admitem fiança.`],a:1,
x:`Os "TTT" são equiparados (art. 5º, XLIII, CF e art. 2º da Lei 8.072/1990), mas não constam do art. 1º.`},

{c:'c12',b:'Vunesp',e:`Em caso de sentença condenatória por crime hediondo, nos termos do art. 2º, § 3º, da Lei nº 8.072/1990,`,
o:[`o réu deverá obrigatoriamente recolher-se à prisão para apelar.`,`o juiz decidirá fundamentadamente se o réu poderá apelar em liberdade.`,`o réu sempre apelará em liberdade.`,`a apelação não tem efeito suspensivo.`,`o recurso é julgado pelo STJ.`],a:1,
x:`Art. 2º, § 3º. A prisão para apelar não é automática; depende dos requisitos da preventiva.`},

{c:'c12',b:'FCC',e:`A extorsão mediante sequestro (art. 159 do CP)`,
o:[`só é hedionda na forma qualificada pelo resultado morte.`,`é hedionda tanto na forma simples quanto nas qualificadas.`,`não é hedionda.`,`é hedionda apenas se a vítima for menor.`,`é equiparada ao terrorismo.`],a:1,
x:`Art. 1º, IV: extorsão mediante sequestro e na forma qualificada (art. 159, caput e §§ 1º, 2º e 3º).`},

/* ===== CAP 13 – DROGAS (extra) ===== */
{c:'c13',b:'Vunesp',e:`Policiais recebem informação de que determinado imóvel é usado como depósito de drogas. Quanto à conduta de "ter em depósito" drogas, é correto afirmar que`,
o:[`é crime instantâneo, consumado no momento da aquisição.`,`é crime permanente, de modo que o flagrante se prolonga enquanto a droga estiver guardada, mas a entrada forçada sem mandado exige fundadas razões, justificadas a posteriori.`,`não é crime, se a droga não for vendida.`,`autoriza a entrada no imóvel a qualquer hora com base apenas na informação anônima.`,`é conduta equiparada ao uso.`],a:1,
x:`O caráter permanente admite flagrante a qualquer tempo, mas o STF (Tema 280) e o STJ exigem fundadas razões concretas; a denúncia anônima isolada não basta.`},

{c:'c13',b:'FCC',e:`Policial que pratica tráfico de drogas prevalecendo-se de sua função pública tem a pena`,
o:[`aplicada em dobro.`,`aumentada de 1/6 a 2/3, nos termos do art. 40, II, da Lei nº 11.343/2006.`,`aumentada de 1/3 até a metade.`,`inalterada, sujeitando-se apenas à perda do cargo.`,`reduzida, se colaborar.`],a:1,
x:`Art. 40, II: prevalecer-se de função pública ou de missão de educação, poder familiar, guarda ou vigilância.`},

{c:'c13',b:'Vunesp',e:`O tráfico de drogas praticado com emprego de arma de fogo`,
o:[`gera concurso material obrigatório com o porte ilegal de arma.`,`tem a pena aumentada de 1/6 a 2/3 pela majorante do art. 40, IV, quando a arma for usada no contexto do tráfico.`,`não sofre aumento de pena.`,`passa a ser crime de terrorismo.`,`é hediondo apenas por esse motivo.`],a:1,
x:`Art. 40, IV. O STJ entende que, se a arma estiver ligada ao tráfico, aplica-se a majorante; se o porte for autônomo, em contexto diverso, há concurso com o crime do Estatuto do Desarmamento.`},

{c:'c13',b:'FCC',e:`Incide a causa de aumento do art. 40, III, da Lei de Drogas quando a infração é cometida nas dependências ou imediações de`,
o:[`residências particulares.`,`unidades militares ou policiais.`,`agências bancárias.`,`postos de gasolina.`,`templos religiosos, exclusivamente.`],a:1,
x:`O art. 40, III, inclui estabelecimentos prisionais, de ensino e hospitalares, entidades estudantis, sociais, culturais, recreativas, esportivas ou beneficentes, locais de trabalho coletivo, espetáculos, serviços de tratamento de dependentes, unidades militares ou policiais e transportes públicos.`},

{c:'c13',b:'Vunesp',e:`No procedimento da Lei de Drogas, oferecida a denúncia, o juiz ordenará a notificação do acusado para oferecer defesa prévia, por escrito, no prazo de`,
o:[`5 dias.`,`10 dias.`,`15 dias.`,`20 dias.`,`30 dias.`],a:1,
x:`Art. 55 da Lei 11.343/2006. Na defesa prévia, o acusado pode arguir preliminares, oferecer documentos e arrolar até 5 testemunhas.`},

{c:'c13',b:'FCC',e:`Em relação ao porte de drogas para consumo pessoal (art. 28), o STF, no julgamento do RE 430.105, em 2007, entendeu que a Lei nº 11.343/2006 promoveu`,
o:[`a abolitio criminis da conduta.`,`a despenalização da conduta, que continuou sendo crime, mas sem pena privativa de liberdade.`,`a criminalização mais severa do usuário.`,`a transformação da conduta em contravenção penal.`,`a legalização de todas as drogas.`],a:1,
x:`Despenalização, não descriminalização. Em 2024 (Tema 506), o STF afastou a natureza penal apenas para a maconha.`},

/* ===== CAP 14 – ESTATUTO PMPE (extra) ===== */
{c:'c14',b:'Vunesp',e:`Na hierarquia da Polícia Militar, o posto de Major integra o círculo de`,
o:[`oficiais subalternos.`,`oficiais intermediários.`,`oficiais superiores.`,`praças especiais.`,`oficiais generais.`],a:2,
x:`Oficiais superiores: Coronel, Tenente-Coronel e Major. Não há oficiais generais nas polícias militares.`},

{c:'c14',b:'FCC',e:`Na escala hierárquica da Polícia Militar, o Subtenente`,
o:[`é oficial subalterno.`,`é praça e integra o círculo de subtenentes e sargentos.`,`é praça especial.`,`é oficial intermediário.`,`está acima do Aspirante-a-Oficial na precedência.`],a:1,
x:`O Subtenente é praça, no círculo de subtenentes e sargentos. Aspirante-a-Oficial e Cadete são praças especiais, com precedência sobre as demais praças.`},

{c:'c14',b:'Vunesp',e:`No âmbito policial-militar, a rigorosa observância e o acatamento integral das leis, regulamentos, normas e disposições que fundamentam o organismo policial-militar, traduzindo-se pelo perfeito cumprimento do dever por parte de todos e de cada um, definem`,
o:[`a hierarquia.`,`a disciplina.`,`o comando.`,`a precedência.`,`a antiguidade.`],a:1,
x:`Definição de disciplina. Hierarquia é a ordenação da autoridade em níveis diferentes, por postos ou graduações.`},

{c:'c14',b:'FCC',e:`Dentro de um mesmo posto ou graduação, a ordenação hierárquica entre policiais militares se faz pela`,
o:[`idade.`,`antiguidade.`,`escolaridade.`,`indicação do Comandante-Geral.`,`lotação.`],a:1,
x:`A hierarquia se faz por postos ou graduações; dentro de um mesmo posto ou graduação, pela antiguidade.`},

{c:'c14',b:'Vunesp',e:`Segundo o Código Penal Militar, comete o crime de deserção o militar que se ausenta, sem licença, da unidade em que serve, ou do lugar em que deve permanecer, por mais de`,
o:[`24 horas.`,`3 dias.`,`8 dias.`,`15 dias.`,`30 dias.`],a:2,
x:`Art. 187 do CPM. Antes disso, o militar é considerado ausente (no modelo do Estatuto, após 24 horas consecutivas).`},

{c:'c14',b:'FCC',e:`É considerado extraviado, no modelo do Estatuto dos Policiais Militares, o militar da ativa cujo desaparecimento se prolongue por mais de`,
o:[`24 horas.`,`8 dias.`,`15 dias.`,`30 dias.`,`90 dias.`],a:3,
x:`Desaparecido: paradeiro ignorado por mais de 8 dias, em serviço, viagem, operação ou calamidade. Extraviado: desaparecimento por mais de 30 dias.`},

{c:'c14',b:'Vunesp',e:`A soma de autoridade, deveres e responsabilidades de que o policial militar é investido legalmente quando conduz homens ou dirige uma organização policial-militar denomina-se`,
o:[`cargo.`,`comando.`,`função.`,`patente.`,`precedência.`],a:1,
x:`Comando. Cargo é o conjunto de atribuições, deveres e responsabilidades; função é o exercício das obrigações do cargo.`},

{c:'c14',b:'FCC',e:`Nos termos do art. 42, § 1º, da Constituição Federal, as patentes dos oficiais das Polícias Militares são conferidas`,
o:[`pelo Presidente da República.`,`pelos respectivos Governadores.`,`pelo Comandante-Geral da corporação.`,`pelo Secretário de Defesa Social.`,`pelo Ministro da Defesa.`],a:1,
x:`Art. 42, § 1º, CF. Nas Forças Armadas, as patentes são conferidas pelo Presidente da República (art. 142, § 3º, I).`},

{c:'c14',b:'Vunesp',e:`Segundo a Constituição Federal, o oficial condenado na justiça comum ou militar a pena privativa de liberdade superior a ___, por sentença transitada em julgado, será submetido ao julgamento sobre a perda do posto e da patente. Assinale a alternativa que preenche a lacuna.`,
o:[`1 ano`,`2 anos`,`4 anos`,`8 anos`,`10 anos`],a:1,
x:`Art. 142, § 3º, VII, aplicável aos militares estaduais (art. 42, § 1º). Ele só perde o posto se julgado indigno do oficialato ou com ele incompatível, por decisão do tribunal competente.`},

{c:'c14',b:'FCC',e:`Policial militar em serviço comete homicídio doloso contra um civil. Nos termos do art. 125, § 4º, da Constituição Federal, a competência para o julgamento é`,
o:[`da Justiça Militar estadual.`,`do Tribunal do Júri.`,`da Justiça Federal.`,`do Superior Tribunal Militar.`,`do Tribunal de Justiça, em instância única.`],a:1,
x:`A Justiça Militar estadual julga os crimes militares, ressalvada a competência do júri quando a vítima for civil.`},

{c:'c14',b:'Vunesp',e:`Entre os preceitos da ética policial-militar, inclui-se o dever de`,
o:[`utilizar o posto ou a graduação para obter facilidades pessoais, desde que lícitas.`,`abster-se de fazer uso do posto ou da graduação para obter facilidades pessoais de qualquer natureza ou para encaminhar negócios particulares ou de terceiros.`,`participar de manifestações coletivas de caráter reivindicatório.`,`manter filiação partidária ativa.`,`comerciar nos horários de folga.`],a:1,
x:`Preceito clássico da ética do Estatuto. Manifestações reivindicatórias coletivas, filiação partidária na ativa e comércio são vedados.`},

/* ===== CAP 15 – PESSOA IDOSA (extra) ===== */
{c:'c15',b:'FCC',e:`Expor a perigo a integridade e a saúde, física ou psíquica, da pessoa idosa, submetendo-a a condições desumanas ou degradantes, é crime punido com detenção de 2 meses a 1 ano e multa. Se do fato resulta a morte, a pena é de`,
o:[`detenção, de 1 a 3 anos.`,`reclusão, de 1 a 4 anos.`,`reclusão, de 4 a 12 anos.`,`reclusão, de 6 a 20 anos.`,`a mesma, aumentada de metade.`],a:2,
x:`Art. 99, § 2º. Com lesão grave: reclusão de 1 a 4 anos (§ 1º).`},

{c:'c15',b:'Vunesp',e:`Negar a alguém, por motivo de idade, emprego ou trabalho constitui crime previsto no Estatuto da Pessoa Idosa, punido com`,
o:[`reclusão, de 6 meses a 1 ano, e multa.`,`detenção, de 1 a 3 anos.`,`reclusão, de 2 a 5 anos.`,`multa, apenas.`,`reclusão, de 1 a 4 anos.`],a:0,
x:`Art. 100, II. O mesmo artigo pune obstar o acesso a cargo público por motivo de idade e recusar atendimento de saúde sem justa causa.`},

{c:'c15',b:'FCC',e:`A entidade de longa permanência que nega o acolhimento ou a permanência da pessoa idosa, como abrigada, por recusa desta em outorgar procuração à entidade comete crime punido com`,
o:[`reclusão, de 2 a 5 anos.`,`detenção, de 6 meses a 1 ano, e multa.`,`reclusão, de 1 a 4 anos.`,`apenas multa administrativa.`,`detenção, de 1 a 3 anos.`],a:1,
x:`Art. 103 do Estatuto da Pessoa Idosa.`},

{c:'c15',b:'Vunesp',e:`Induzir pessoa idosa sem discernimento de seus atos a outorgar procuração para fins de administração de bens ou deles dispor livremente é crime punido com`,
o:[`detenção, de 6 meses a 1 ano.`,`reclusão, de 2 a 4 anos.`,`reclusão, de 2 a 5 anos.`,`detenção, de 1 a 3 anos.`,`reclusão, de 1 a 4 anos.`],a:1,
x:`Art. 106. A mesma pena vale para o tabelião que lavra ato notarial envolvendo idoso sem discernimento e sem representação legal (art. 108). Coagir o idoso (art. 107): 2 a 5 anos.`},

{c:'c15',b:'FCC',e:`Impedir ou embaraçar ato do representante do Ministério Público ou de qualquer outro agente fiscalizador, no âmbito do Estatuto da Pessoa Idosa, é crime punido com`,
o:[`detenção, de 1 a 3 meses.`,`reclusão, de 6 meses a 1 ano, e multa.`,`reclusão, de 2 a 4 anos.`,`detenção, de 1 a 3 anos.`,`multa, apenas.`],a:1,
x:`Art. 109 do Estatuto da Pessoa Idosa.`},

{c:'c15',b:'Vunesp',e:`Um cuidador contratado humilha e menospreza, por qualquer motivo, a pessoa idosa que está sob seus cuidados. Nos termos do art. 96 do Estatuto,`,
o:[`a conduta é atípica, se não houver lesão.`,`a conduta configura crime, com pena aumentada de 1/3 por estar a vítima sob os cuidados ou responsabilidade do agente.`,`a conduta configura apenas injúria simples.`,`a pena é aplicada em dobro.`,`a ação penal depende de representação.`],a:1,
x:`Art. 96, §§ 1º e 2º (reclusão de 6 meses a 1 ano e multa, aumentada de 1/3). Ação penal pública incondicionada (art. 95).`},

{c:'c15',b:'FCC',e:`No sistema de transporte coletivo interestadual, o Estatuto da Pessoa Idosa assegura`,
o:[`gratuidade a todas as pessoas idosas, sem limite de vagas.`,`a reserva de 2 vagas gratuitas por veículo para pessoas idosas com renda igual ou inferior a 2 salários mínimos, e desconto de 50%, no mínimo, no valor das passagens, para as que excederem as vagas gratuitas, com a mesma renda.`,`desconto de 30% a todas as pessoas idosas.`,`1 vaga gratuita por veículo, sem requisito de renda.`,`gratuidade apenas aos maiores de 80 anos.`],a:1,
x:`Art. 40 do Estatuto. Compare com o Estatuto da Juventude: 2 vagas gratuitas e 2 com 50% de desconto para jovens de baixa renda.`},

{c:'c15',b:'Vunesp',e:`O Estatuto da Pessoa Idosa assegura a reserva, nos estacionamentos públicos e privados, de`,
o:[`2% das vagas.`,`5% das vagas.`,`10% das vagas.`,`20% das vagas.`,`uma vaga por andar.`],a:1,
x:`Art. 41 do Estatuto. Nos transportes coletivos urbanos, 10% dos assentos são reservados (art. 39, § 2º).`},

{c:'c15',b:'FCC',e:`Verificada ameaça ou violação dos direitos da pessoa idosa, as medidas específicas de proteção previstas no art. 45 do Estatuto podem ser determinadas`,
o:[`apenas pelo Conselho Tutelar.`,`pelo Ministério Público ou pelo Poder Judiciário, a requerimento daquele.`,`apenas pela autoridade policial.`,`pelo Conselho Municipal da Pessoa Idosa, exclusivamente.`,`pela própria pessoa idosa.`],a:1,
x:`Art. 45. Entre as medidas: encaminhamento à família ou curador, orientação e apoio temporários, requisição de tratamento de saúde, abrigo em entidade e abrigo temporário.`},

{c:'c15',b:'Vunesp',e:`Nos termos do art. 6º do Estatuto da Pessoa Idosa, o dever de comunicar à autoridade competente qualquer forma de violação à lei que tenha testemunhado ou de que tenha conhecimento cabe`,
o:[`apenas aos profissionais de saúde.`,`a todo cidadão.`,`apenas aos familiares.`,`apenas aos servidores públicos.`,`apenas ao Ministério Público.`],a:1,
x:`Art. 6º. Os serviços de saúde têm ainda a obrigação específica de notificação compulsória (art. 19).`},

{c:'c15',b:'FCC',e:`Deixar de cumprir, retardar ou frustrar, sem justo motivo, a execução de ordem judicial expedida nas ações em que for parte ou interveniente a pessoa idosa é crime punido com`,
o:[`detenção, de 6 meses a 1 ano, e multa.`,`reclusão, de 2 a 4 anos.`,`apenas multa.`,`reclusão, de 1 a 4 anos.`,`detenção, de 1 a 3 anos.`],a:0,
x:`Art. 101 do Estatuto da Pessoa Idosa.`},

/* ===== CAP 16 – JUVENTUDE (extra) ===== */
{c:'c16',b:'Vunesp',e:`Um rapaz de 22 anos busca políticas públicas de inserção no mercado de trabalho. Os direitos aplicáveis a ele, na condição de jovem, estão previstos`,
o:[`no Estatuto da Criança e do Adolescente.`,`no Estatuto da Juventude.`,`no Estatuto da Pessoa Idosa.`,`exclusivamente na CLT.`,`em ambos os Estatutos, da Criança e da Juventude, igualmente.`],a:1,
x:`Entre 18 e 29 anos, aplica-se só o Estatuto da Juventude. O ECA vai até os 18 (excepcionalmente, 21).`},

{c:'c16',b:'FCC',e:`Segundo o art. 14 do Estatuto da Juventude, o jovem tem direito à profissionalização, ao trabalho e à renda, exercido em condições de`,
o:[`subordinação e disciplina.`,`liberdade, equidade e segurança, adequadamente remunerado e com proteção social.`,`aprendizagem obrigatória até os 24 anos.`,`exclusividade no serviço público.`,`dedicação exclusiva, vedado o estudo.`],a:1,
x:`Literalidade do art. 14.`},

{c:'c16',b:'Vunesp',e:`Nos termos do art. 17 do Estatuto da Juventude, o jovem não será discriminado por motivo de`,
o:[`antecedentes criminais, apenas.`,`etnia, raça, cor da pele, cultura, origem, idade e sexo; orientação sexual, idioma ou religião; opinião, deficiência e condição social ou econômica.`,`escolaridade, apenas.`,`nacionalidade, exclusivamente.`,`filiação partidária, apenas.`],a:1,
x:`Art. 17, I a III (Seção IV – Do Direito à Diversidade e à Igualdade).`},

{c:'c16',b:'FCC',e:`Segundo o Estatuto da Juventude, o jovem tem direito à participação social e política e`,
o:[`ao voto obrigatório a partir dos 15 anos.`,`na formulação, execução e avaliação das políticas públicas de juventude.`,`à filiação partidária automática.`,`à candidatura a cargos eletivos a partir dos 16 anos.`,`ao mandato nos conselhos tutelares.`],a:1,
x:`Art. 4º. A interlocução com o poder público pode ocorrer por associações, redes, movimentos e organizações juvenis (art. 5º).`},

{c:'c16',b:'Vunesp',e:`O benefício da meia-entrada em eventos artístico-culturais e esportivos, previsto no Estatuto da Juventude e regulamentado pela Lei nº 12.933/2013, é assegurado`,
o:[`a todos os jovens de 15 a 29 anos, independentemente de renda.`,`aos estudantes e aos jovens de 15 a 29 anos de baixa renda.`,`apenas aos estudantes universitários.`,`apenas aos jovens desempregados.`,`a qualquer pessoa com até 35 anos.`],a:1,
x:`Seção VI (Do Direito à Cultura), art. 23, regulamentado pela Lei 12.933/2013. A comprovação da baixa renda é feita pela Identidade Jovem.`},

{c:'c16',b:'FCC',e:`O Sistema Nacional de Juventude (SINAJUVE), instituído pelo Estatuto da Juventude,`,
o:[`é órgão jurisdicional vinculado ao Poder Judiciário.`,`tem composição, organização, competência e funcionamento definidos em regulamento.`,`substitui os Conselhos Tutelares.`,`é composto exclusivamente por jovens eleitos.`,`foi extinto em 2019.`],a:1,
x:`Art. 39 do Estatuto da Juventude.`},

{c:'c16',b:'Vunesp',e:`Entre as diretrizes das políticas de segurança pública voltadas para os jovens, o Estatuto da Juventude inclui a promoção de estudos e pesquisas e a obtenção de estatísticas e informações relevantes para`,
o:[`aumentar o efetivo policial nas escolas.`,`subsidiar as ações de segurança pública e permitir a avaliação periódica dos impactos das políticas públicas quanto às causas, às consequências e à frequência da violência contra os jovens.`,`criar cadastro nacional de jovens infratores.`,`restringir a circulação noturna de jovens.`,`fundamentar a redução da maioridade penal.`],a:1,
x:`Art. 38, III, do Estatuto da Juventude.`},

{c:'c16',b:'FCC',e:`O Estatuto da Juventude prevê, entre as diretrizes das políticas de segurança pública voltadas para os jovens, a promoção do efetivo acesso dos jovens com deficiência à justiça em igualdade de condições com as demais pessoas,`,
o:[`desde que acompanhados de curador.`,`inclusive mediante a provisão de adaptações processuais adequadas a sua idade.`,`somente nos juizados especiais.`,`apenas após os 21 anos.`,`mediante autorização do Ministério Público.`],a:1,
x:`Art. 38, VI, do Estatuto da Juventude.`},

{c:'c16',b:'Vunesp',e:`Entre as diretrizes gerais das políticas públicas de juventude, o Estatuto prevê zelar pelos direitos dos jovens`,
o:[`com idade entre 15 e 17 anos em cumprimento de medida socioeducativa, exclusivamente.`,`com idade entre 18 e 29 anos privados de liberdade e egressos do sistema prisional, formulando políticas de educação e trabalho, incluindo estímulos à sua reinserção social e laboral.`,`estrangeiros em situação irregular, apenas.`,`que prestam serviço militar obrigatório.`,`universitários, exclusivamente.`],a:1,
x:`Diretriz do art. 3º, que prevê também oportunidades de estudo e trabalho que favoreçam o cumprimento do regime semiaberto.`},

{c:'c16',b:'FCC',e:`Segundo o Estatuto da Juventude, entre os princípios que regem as políticas públicas de juventude está o reconhecimento do jovem como sujeito de direitos`,
o:[`tutelados pela família até os 29 anos.`,`universais, geracionais e singulares.`,`exclusivamente sociais.`,`subordinados aos da criança.`,`limitados à esfera econômica.`],a:1,
x:`Art. 2º, IV, do Estatuto da Juventude.`},

{c:'c16',b:'Vunesp',e:`<p>Considere as afirmações sobre o Estatuto da Juventude:</p><ol type="I"><li>São jovens as pessoas com idade entre 15 e 29 anos.</li><li>Aos adolescentes entre 15 e 18 anos aplica-se exclusivamente o Estatuto da Juventude.</li><li>O direito à segurança pública e ao acesso à justiça está entre os direitos previstos no Estatuto.</li></ol><p>Está correto o que se afirma APENAS em</p>`,
o:[`I.`,`I e II.`,`I e III.`,`II e III.`,`III.`],a:2,
x:`I e III corretas (art. 1º, § 1º; Seção XI). II errada: entre 15 e 18 anos aplica-se o ECA e, excepcionalmente, o Estatuto da Juventude (art. 1º, § 2º).`},

/* ===== CAP 17 – SÚMULAS (extra) ===== */
{c:'c17',b:'Vunesp',e:`Segundo a Súmula 145 do STF, não há crime quando`,
o:[`o agente desiste voluntariamente da execução.`,`a preparação do flagrante pela polícia torna impossível a sua consumação.`,`a polícia acompanha a ação criminosa para prender o maior número de agentes.`,`o agente é preso em flagrante esperado.`,`o crime é de menor potencial ofensivo.`],a:1,
x:`Flagrante preparado = crime impossível. O flagrante esperado (a polícia apenas aguarda, sem provocar) e a ação controlada são válidos.`},

{c:'c17',b:'FCC',e:`Segundo a Súmula 419 do STJ,`,
o:[`é cabível a prisão civil do depositário judicial infiel.`,`descabe a prisão civil do depositário judicial infiel.`,`a prisão civil do devedor de alimentos é ilícita.`,`a prisão civil por dívida fiscal é admitida.`,`o depositário infiel responde por apropriação indébita, obrigatoriamente.`],a:1,
x:`Súmula 419 STJ, em harmonia com a SV 25 (qualquer modalidade de depósito). A única prisão civil admitida é a do devedor de alimentos.`},

{c:'c17',b:'Vunesp',e:`No julgamento da ADI 6.138, o STF decidiu que o art. 12-C da Lei Maria da Penha, que permite ao delegado e ao policial afastar o agressor do lar em municípios que não sejam sede de comarca,`,
o:[`é inconstitucional, por violar a reserva de jurisdição.`,`é constitucional.`,`é constitucional apenas quanto ao delegado.`,`foi suspenso até a criação dos Juizados.`,`só se aplica em capitais.`],a:1,
x:`O STF entendeu que a medida, provisória e submetida ao juiz em 24 horas, é proporcional diante do risco à vida da mulher.`},

{c:'c17',b:'FCC',e:`No ARE 654.432, o STF fixou a tese de que o exercício do direito de greve, sob qualquer forma ou modalidade, é vedado`,
o:[`apenas aos militares das Forças Armadas.`,`aos policiais civis e a todos os servidores públicos que atuem diretamente na área de segurança pública.`,`a todos os servidores públicos.`,`apenas aos policiais federais.`,`apenas aos guardas municipais.`],a:1,
x:`Tese do Tema 541. Aos militares (inclusive PMs), a proibição já é expressa na CF (art. 142, § 3º, IV).`},

{c:'c17',b:'Vunesp',e:`Na ADPF 347, o STF reconheceu, quanto ao sistema prisional brasileiro,`,
o:[`a regularidade das condições carcerárias.`,`o estado de coisas inconstitucional, determinando, entre outras medidas, a realização de audiências de custódia.`,`a inconstitucionalidade da prisão preventiva.`,`a obrigatoriedade de privatização dos presídios.`,`a competência da União para todos os presídios.`],a:1,
x:`ADPF 347 (cautelar em 2015, mérito em 2023): violação massiva de direitos fundamentais dos presos e omissão estrutural do poder público.`},

{c:'c17',b:'FCC',e:`Segundo a Súmula 607 do STJ, a majorante do tráfico transnacional de drogas (art. 40, I, da Lei nº 11.343/2006)`,
o:[`exige a efetiva transposição da fronteira.`,`configura-se com a prova da destinação internacional das drogas, ainda que não consumada a transposição de fronteiras.`,`só incide se a droga for apreendida no exterior.`,`desloca a competência para a Justiça Estadual.`,`não se aplica a estrangeiros.`],a:1,
x:`Súmula 607 STJ. A mesma lógica vale para o tráfico interestadual (Súmula 587 STJ).`},

{c:'c17',b:'Vunesp',e:`Segundo a Súmula 501 do STJ, é cabível a aplicação retroativa da Lei nº 11.343/2006, desde que o resultado da incidência das suas disposições, na íntegra, seja mais favorável ao réu do que o advindo da aplicação da Lei nº 6.368/1976,`,
o:[`sendo permitida a combinação das partes mais benéficas de cada lei.`,`sendo vedada a combinação de leis.`,`apenas para crimes cometidos após 2006.`,`desde que haja requerimento do Ministério Público.`,`desde que o réu seja primário.`],a:1,
x:`Súmula 501 do STJ: aplica-se uma lei ou outra, por inteiro.`},

{c:'c17',b:'FCC',e:`No HC 154.248, em 2021, o STF decidiu que o crime de injúria racial`,
o:[`prescreve normalmente, por ser crime contra a honra.`,`é espécie do gênero racismo, sendo, portanto, imprescritível.`,`é crime de ação penal privada.`,`não pode ser praticado contra servidor público.`,`foi revogado pela Lei nº 7.716/1989.`],a:1,
x:`Depois da decisão, a Lei 14.532/2023 levou a injúria racial para a Lei 7.716/1989 (art. 2º-A), com pena de reclusão de 2 a 5 anos.`},

{c:'c17',b:'Vunesp',e:`No REsp 1.977.124/SP, em 2022, o STJ decidiu que a Lei Maria da Penha`,
o:[`não se aplica a mulheres trans, por exigir o sexo biológico feminino.`,`aplica-se às mulheres trans, pois o elemento que justifica a proteção é o gênero.`,`aplica-se a homens vítimas de violência doméstica.`,`só se aplica se houver coabitação.`,`não se aplica a relações homoafetivas.`],a:1,
x:`Decisão da 6ª Turma do STJ. A lei também se aplica a relações homoafetivas entre mulheres (art. 5º, parágrafo único).`}
);
